), matched as (
  select p.id, official_entrances.entrances
  from official_entrances
  join place_transit_sources pts
    on pts.source_key = 'mta-subway:complex:' || official_entrances.complex_id
  join places p on p.id = pts.place_id
  where p.status = 'published'
    and p.facility_type = 'rail_station'
)
, saved_originals as (
  insert into place_transit_originals_20260912 (place_id, original_record)
  select p.id, to_jsonb(p)
  from places p
  join matched on matched.id = p.id
  on conflict (place_id) do nothing
  returning place_id
)
update places p
set transit_details = jsonb_set(
      coalesce(p.transit_details, '{}'::jsonb),
      '{entrances}',
      coalesce((
        select jsonb_agg(item order by item->>'name', item->>'side', item->>'direction')
        from (
          select item
          from jsonb_array_elements(
            case when jsonb_typeof(p.transit_details->'entrances') = 'array'
              then p.transit_details->'entrances' else '[]'::jsonb end
          ) as item
          union
          select item
          from jsonb_array_elements(matched.entrances) as item
        ) combined_entrances
      ), '[]'::jsonb),
      true
    ),
    updated_at = now()
from matched
where p.id = matched.id;
